/// Convert a Pokémon species name to its base species.
/// 
/// If the species is a form (e.g., "landorustherian"), returns the base species ("landorus").
/// Otherwise, returns the species name unchanged.
pub fn to_base_species(species: &str) -> &str {
    let map = get_base_species_map();
    map.get(species).copied().unwrap_or(species)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_base_species_mapping() {
        // Form -> base species
        assert_eq!(to_base_species("landorustherian"), "landorus");
        assert_eq!(to_base_species("basculinbluestriped"), "basculin");
        
        // Base species -> unchanged
        assert_eq!(to_base_species("pikachu"), "pikachu");
        assert_eq!(to_base_species("landorus"), "landorus");
    }
}
